#!/usr/bin/env python3
"""Sync the latest Version B code; preserve images and back up previous code."""
from pathlib import Path
import sys,json,gzip,base64,datetime
PAYLOAD = ''
root=Path(sys.argv[1] if len(sys.argv)>1 else 'gallery-direct-version-b').resolve()
dist=root/'dist'
if not (dist/'index.html').is_file():raise SystemExit('Cannot find Version B dist/index.html. Run from the GitHub repository root.')
files=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
backup=root.parent/('gallery-version-b-backup-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f'))
count=0
for name,value in files.items():
 target=dist/name;data=base64.b64decode(value)
 if target.is_file() and target.read_bytes()==data:continue
 if target.exists():
  saved=backup/'dist'/name;saved.parent.mkdir(parents=True,exist_ok=True);saved.write_bytes(target.read_bytes())
 target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data);count+=1
print(f'Updated {count} Version B code files. Images and asset folders preserved.')
if count:print(f'Previous code backed up: {backup}')
print('Refresh your preview, then commit and push the Version B dist folder.')
